const {test}=require('node:test'),assert=require('node:assert/strict');
const {collectCloudRun,validateCloudRun}=require('./cloud-run');
const commit='a'.repeat(40),repository='VeamStudios/CloudServices';
const options={commit,repository,project:'veam-cloud-services',region:'europe-west1',evidence:'https://example.com/run'};
const good=()=>({kind:'cloud-run',...options,checkedAt:new Date().toISOString(),components:['email','exporter','main','pdf'].map(service=>({service,revision:service+'-00001',commit,ready:true,trafficPercent:100}))});
test('CloudServices requires all four exact serving commits and complete traffic',()=>{assert.equal(validateCloudRun(good(),commit,repository).components.length,4);for(const mutate of [v=>v.components.pop(),v=>v.components[1]=v.components[0],v=>v.components[0].commit='b'.repeat(40),v=>v.components[0].trafficPercent=50,v=>v.components[0].ready=false,v=>v.project='dev']){const v=good();mutate(v);assert.throws(()=>validateCloudRun(v,commit,repository))}});
test('collects the serving revision label, not the latest service template',()=>{const reads=[];const v=collectCloudRun(options,args=>{reads.push(args);if(args[1]==='services')return{spec:{template:{metadata:{labels:{commit_hash:'b'.repeat(40)}}}},status:{conditions:[{type:'Ready',status:'True'}],traffic:[{revisionName:args[3]+'-00001',percent:100}]}};return{metadata:{labels:{commit_hash:commit}},status:{conditions:[{type:'Ready',status:'True'}]}}});assert.equal(v.commit,commit);assert.equal(reads.length,8)});
test('split traffic and provider failures remain pending evidence',()=>{assert.throws(()=>collectCloudRun(options,()=>({status:{conditions:[{type:'Ready',status:'True'}],traffic:[{revisionName:'old',percent:10},{revisionName:'new',percent:90}]}})));assert.throws(()=>collectCloudRun(options,()=>{throw new Error('permission denied')}),/permission denied/)});
